# -*- coding: utf-8 -*-
from pathlib import Path
import base64,html,json
B=Path(__file__).resolve().parent
ROOT=B.parents[1]
a=json.loads((B/'analysis.json').read_text())
def image(name):return 'data:image/png;base64,'+base64.b64encode((B/name).read_bytes()).decode()
LABELS={'KP_h_Mpc':'kₚ / h Mpc⁻¹','MS':'mₛ'}
rows=''.join(f'<tr><td>{LABELS[r["parameter"]]}</td><td>{r["median"]:.3f}</td><td>[{r["q025"]:.3f}, {r["q975"]:.3f}]</td><td>[{r["prior_low"]}, {r["prior_high"]}]</td><td>{100*r["width95_over_prior_equal_tail95"]:.1f}%</td></tr>' for r in a['intervals'] if r['selection']=='last300')
links=' '.join(f'<a download="{n}" href="data:application/octet-stream;base64,{base64.b64encode((B/n).read_bytes()).decode()}">{label}</a>' for n,label in [('README.md','分析与补跑清单'),('TASKS.md','按顺序任务清单'),('intervals.csv','区间 CSV'),('analysis.json','核验 JSON')])
s=f'''<!doctype html><html lang="zh"><meta charset="utf-8"><title>BTemu · KP / MS 边缘后验</title><link rel="icon" href="data:,"><style>body{{margin:0;background:#f3f5f6;color:#283e4c;font:16px/1.7 system-ui}}main{{width:1120px;margin:48px auto}}h1{{font-size:34px;margin-bottom:12px}}p{{max-width:970px}}.tag{{color:#647b87;font-size:13px;letter-spacing:2px}}section{{background:white;border:1px solid #dce3e7;padding:28px;margin:24px 0}}img{{display:block;width:100%;height:auto}}table{{width:100%;border-collapse:collapse;font-variant-numeric:tabular-nums}}td,th{{padding:13px;text-align:left;border-bottom:1px solid #e1e7ea}}a{{color:#285e7a;margin-right:24px}}.caption{{font-size:14px;color:#5d6e79}}li{{margin:10px 0}}</style><main><div class="tag">BTEMU / INFERENCE / 2026-11-06</div><h1>kₚ 与 mₛ：边缘分布及先验对照</h1><p>100k 模型 · 600 步 × 32 walkers · 边缘化六个天体物理参数。主图采用后 300 步，共 9,600 行；这是可复现的初步样本统计，完整选样对照随 CSV 提供。</p><section><table><thead><tr><th>参数</th><th>中位数</th><th>95% 等尾区间</th><th>参考先验</th><th>宽度 / 先验95%宽度</th></tr></thead><tbody>{rows}</tbody></table><p>kₚ 的变化主要在低值端；mₛ 范围接近参考先验。当前链需继续采样及独立运行检查，才能形成最终区间。</p></section><section><img alt="KP MS marginal distributions and prior reference" src="{image('kp_ms_marginal_prior.png')}"><p class="caption">蓝色：后 300 步边缘分布；橙色虚线：归档均匀先验。竖虚线及上方数字为一维 95% 等尾区间；灰填色为二维 95% 平滑样本密度区域。先验来自归档表，本次 HDF5 未附实际运行配置。</p></section><section><h2>时间稳定性</h2><img alt="Walker traces and first versus last 300 steps" src="{image('kp_ms_stability.png')}"><p class="caption">左：32 个 walker 轨迹与逐步中位数；右：前后 300 步的边缘分布。当前相关时间估计约 52–58 步，全链仅约 10–11 倍该估计。</p></section><section><h2>下一步，按顺序</h2><ol><li>补齐本次 100k 配置、checkpoint；导出 65k 的 16,018 步链，分开保留。</li><li>延长现有 100k 8D 链，每增加 2,000 步检查一次。</li><li>再补三组独立初值的 100k 8D ensemble，合计四组；各先检查 3,000–5,000 步结果，再决定延长量。</li><li>根据独立运行一致性、有效样本量及区间端点误差确定留样并给出最终约束。</li><li>若需解释各观测的贡献，再做 LF-only / LF+tau / LF+tau+xHI 的 8D 对照。</li></ol><p>65k 和 100k 链未混合。本次仅分析文件，未启动补跑。</p>{links}</section></main></html>'''
(B/'index.html').write_text(s)
out=ROOT/'output/html/BTemu_kpms_posterior_20261106.html';out.parent.mkdir(parents=True,exist_ok=True);out.write_text(s)
print(out)
